binarios_palindromos.src:
def solve(params: dict) -> int:
    n = int(params["n"])
    if n <= 0:
        return 0

    L = n.bit_length()
    total = 0

    for length in range(1, L):
        total += 1 << ((length - 1) // 2)

    h = (L + 1) // 2
    base = 1 << (h - 1)
    suffix_len = L - h
    prefix = n >> suffix_len

    if suffix_len == 0:
        rev = 0
    else:
        s = bin(prefix)[2:]
        if L % 2 == 0:
            rev_s = s[::-1]
        else:
            rev_s = s[:-1][::-1]
        rev = int(rev_s, 2) if rev_s else 0

    n_suffix = n & ((1 << suffix_len) - 1)

    if rev <= n_suffix:
        max_p = prefix
    else:
        max_p = prefix - 1

    if max_p >= base:
        total += max_p - base + 1

    return total

