def solve(params: dict) -> int:
    coins = params["coins"]
    amt = params["amt"]
    INF = 10**9
    dp = [INF] * (amt + 1)
    dp[0] = 0
    for i in range(1, amt + 1):
        for c in coins:
            if i >= c and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    return dp[amt] if dp[amt] != INF else -1

