def solve(params: dict) -> int:
    n = int(params["n"])
    m = int(params["m"])

    def fib_pair(k):
        if k == 0:
            return 0, 1
        a, b = fib_pair(k >> 1)
        c = (a * ((2 * b - a) % m)) % m
        d = (a * a + b * b) % m
        if k & 1:
            return d, (c + d) % m
        return c, d

    return fib_pair(n)[0]

grilla_obstaculo.src:
from math import comb

def solve(params: dict) -> int:
    R = params["R"]
    C = params["C"]
    bx = params["bx"]
    by = params["by"]

    def paths(dx: int, dy: int) -> int:
        return comb(dx + dy, dx)

    total = paths(R, C)

    if 0 <= bx <= R and 0 <= by <= C:
        if (bx, by) == (0, 0) or (bx, by) == (R, C):
            return 0
        through = paths(bx, by) * paths(R - bx, C - by)
        return total - through

    return total

islas.src:
def solve(params: dict) -> int:
    g = params["g"]
    if not g:
        return 0

    n = len(g)
    m = len(g[0])
    seen = set()
    islands = 0

    for i in range(n):
        for j in range(m):
            if g[i][j] == '1' and (i, j) not in seen:
                islands += 1
                stack = [(i, j)]
                seen.add((i, j))

                while stack:
                    x, y = stack.pop()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if g[nx][ny] == '1' and (nx, ny) not in seen:
                                seen.add((nx, ny))
                                stack.append((nx, ny))

    return islands

