libres_cuadrados.src:
import math

def solve(params: dict) -> int:
    n = int(params["n"])
    if n <= 0:
        return 0

    limit = math.isqrt(n)
    mu = [0] * (limit + 1)
    mu[1] = 1

    primes = []
    is_composite = [False] * (limit + 1)

    for i in range(2, limit + 1):
        if not is_composite[i]:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            v = i * p
            if v > limit:
                break
            is_composite[v] = True
            if i % p == 0:
                mu[v] = 0
                break
            else:
                mu[v] = -mu[i]

    total = 0
    for d in range(1, limit + 1):
        if mu[d] != 0:
            total += mu[d] * (n // (d * d))

    return total

