import math

def solve(params: dict) -> int:
    n = int(params["n"])
    if n < 1:
        return 0
    L = math.isqrt(n)
    mu = [0] * (L + 1)
    if L >= 1:
        mu[1] = 1
    primes = []
    comp = bytearray(L + 1)
    for i in range(2, L + 1):
        if comp[i] == 0:
            primes.append(i)
            mu[i] = -1
        for p in primes:
            v = i * p
            if v > L:
                break
            comp[v] = 1
            if i % p == 0:
                mu[v] = 0
                break
            mu[v] = -mu[i]
    ans = 0
    for d in range(1, L + 1):
        m = mu[d]
        if m:
            ans += m * (n // (d * d))
    return ans

