import math

def solve(params: dict) -> int:
    n = int(params["n"])
    s = int(params["s"])
    if n <= 0 or s < 1 or s > 9 * n:
        return 0

    S = s - 1
    N = n - 1
    total = 0

    max_b = min(N, S // 10)
    for b in range(max_b + 1):
        rem = S - 10 * b
        term = math.comb(N, b) * math.comb(rem + N, N)
        if b % 2 == 0:
            total += term
        else:
            total -= term

    if S >= 9:
        S2 = S - 9
        max_b = min(N, S2 // 10)
        for b in range(max_b + 1):
            rem = S2 - 10 * b
            term = math.comb(N, b) * math.comb(rem + N, N)
            if b % 2 == 0:
                total -= term
            else:
                total += term

    return total

