        return 2
    if n < 6:
        limit = 15
    else:
        limit = int(n * (math.log(n) + math.log(math.log(n)))) + 10
    primes = []
    while len(primes) < n:
        sieve = bytearray(b'\x01') * (limit + 1)
        sieve[0:2] = b'\x00\x00'
        for i in range(2, int(limit ** 0.5) + 1):
            if sieve[i]:
                start = i * i
                sieve[start:limit + 1:i] = b'\x00' * (((limit - start) // i) + 1)
        primes = [i for i in range(2, limit + 1) if sieve[i]]
        limit *= 2
    return primes[n - 1]

