def solve(params: dict) -> int:
    s = params["s"]
    t = ["^"]
    for ch in s:
        t.append("#")
        t.append(ch)
    t.append("#")
    t.append("$")

    p = [0] * len(t)
    c = 0
    r = 0

    for i in range(1, len(t) - 1):
        if i < r:
            p[i] = min(r - i, p[2 * c - i])
        while t[i - p[i] - 1] == t[i + p[i] + 1]:
            p[i] += 1
        if i + p[i] > r:
            c = i
            r = i + p[i]

    ans = 0
    for i in range(1, len(t) - 1):
        ans += (p[i] + 1) // 2
    return ans

