def solve(params: dict) -> int:
    n = params["n"]
    if n < 0:
        return 0
    if n == 0:
        return 1

    m = n
    while m % 2 == 0:
        m //= 2

    ways = 1
    p = 3
    while p * p <= m:
        if m % p == 0:
            e = 0
            while m % p == 0:
                m //= p
                e += 1
            if p % 4 == 3:
                if e % 2 == 1:
                    return 0
            else:
                ways *= e + 1
        p += 2

    if m > 1:
        if m % 4 == 3:
            return 0
        if m % 4 == 1:
            ways *= 2

    return 4 * ways

