def solve(params: dict) -> int:
    n = params["n"]
    k = params["k"]
    if n < 0 or k < 0:
        return 0
    if k == 0:
        return 1 if n == 0 else 0
    if k > n:
        return 0

    dp = [0] * (k + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        new = [0] * (k + 1)
        for j in range(1, min(i, k) + 1):
            new[j] = dp[j - 1] + j * dp[j]
        dp = new

    return dp[k]

