    d = params["d"]
    dp = [[0] * d for _ in range(k + 1)]
    dp[0][0] = 1
    for x in a:
        r = x % d
        for j in range(k - 1, -1, -1):
            for rem in range(d):
                val = dp[j][rem]
                if val:
                    dp[j + 1][(rem + r) % d] += val
    return dp[k][0]

