import math

def solve(params: dict) -> int:
    n = int(params["n"])
    if n <= 0:
        return 0

    limit = 15 if n < 6 else int(n * (math.log(n) + math.log(math.log(n)))) + 10

    while True:
        sieve = bytearray(b'\x01') * (limit + 1)
        if limit >= 0:
            sieve[0] = 0
        if limit >= 1:
            sieve[1] = 0

        for i in range(2, int(limit ** 0.5) + 1):
            if sieve[i]:
                start = i * i
                step = i
                count = ((limit - start) // step) + 1
                sieve[start:limit + 1:step] = b'\x00' * count

        primes = [i for i in range(limit + 1) if sieve[i]]
        if len(primes) >= n:
            return sum(primes[:n])

        limit *= 2

